<script setup>
import { computed, onMounted, onUnmounted, ref, watch } from 'vue';
import SecurityPanel from './SecurityPanel.vue';
import NotificationsPanel from './NotificationsPanel.vue';
const props = defineProps({ api: Function, user: Object });
const emit = defineEmits(['logout']);
const page = ref('overview'), loading = ref(false), busy = ref(false), error = ref(''), notice = ref('');
const overview = ref({}), customers = ref(null), sales = ref(null), installations = ref(null), tickets = ref(null), users = ref(null), settings = ref(null), audit = ref(null);
const search = ref(''), currentPage = ref(1), customer = ref(null), selectedId = ref('');
const customerForm = ref({ name: '', slug: '', owner_email: '', create_owner:false, owner_name:'', owner_password:'', owner_password_confirmation:'', current_password:'' }), showCreate = ref(false);
const quote = ref(null), quoteForm = ref({ amount_vnd: '', service_days: 30, terms: '' });
const payment = ref(null), paymentForm = ref({ reference: '', amount_vnd: '', confirmed_received: false, defer_installation: true });
const installForm = ref({ driver: 'simulation', notes: '', confirmed: false });
const installEnabled = computed(() => !!settings.value && (installForm.value.driver === 'simulation' ? settings.value.simulation_enabled : settings.value.live_enabled && (installForm.value.driver !== 'ssh' || settings.value.ssh_enabled)));
const sshForm = ref({ssh_host:'',ssh_port:22,ssh_user:'root',ssh_password:'',ssh_host_key:'',dedicated_server:false,current_password:''});
watch(()=>installForm.value.driver,()=>{sshForm.value.ssh_password='';sshForm.value.current_password='';sshForm.value.dedicated_server=false;installForm.value.confirmed=false;});
const credentialTarget=ref(null), credentialPassword=ref(''), credentialCurrent=ref('');
const cancelTarget=ref(null),cancelChecked=ref(false),sshCheck=ref('');
watch(()=>JSON.stringify(sshForm.value),()=>{sshCheck.value='';});
const retryTarget = ref(null), retryChecked = ref(false), handover = ref(null);
const acceptance = ref({ database_checked: false, tls_checked: false, connector_checked: false, radius_checked: false, backup_checked: false, evidence: '' });
const replyTarget = ref(null), reply = ref(''), closeTicket = ref(false);
const navigation = [['overview','◈','Tổng quan TN20'],['customers','▦','Khách hàng'],['sales','◇','Bán hàng & thanh toán'],['installations','▤','Cài đặt cho khách'],['tickets','◌','Hỗ trợ khách hàng'],['users','♙','Tài khoản'],['settings','⚙','Cấu hình hệ thống'],['audit','◷','Nhật ký admin'],['security','◇','Bảo mật tài khoản'],['notifications','◉','Thông báo']];
const labels = { checking_ssh_target:'Kiểm tra thông tin máy', checking_ssh_connection:'Kiểm tra kết nối SSH và tài nguyên', configuring_dns:'Cấu hình DNS', installing_packages:'Cài bộ NAC20', installation_simulated:'Đã mô phỏng cài đặt',  active:'Hoạt động', suspended:'Tạm ngưng', requested:'Đã yêu cầu', quoted:'Báo giá đã gửi', pending_payment:'Chờ thanh toán', pending_review:'Chờ đối soát', paid:'Đã thanh toán', cancelled:'Đã hủy', queued:'Đang chờ', running:'Đang chạy', completed:'Hoàn tất tác vụ', failed:'Cần xử lý', simulated:'Đã mô phỏng', provisioning:'Đang cài đặt', awaiting_configuration:'Chờ cấu hình / nghiệm thu', ready:'Đã bàn giao', open:'Đang tiếp nhận', answered:'Đã phản hồi', closed:'Đã đóng' };
const state = value => labels[value] || value;
const money = value => new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(value || 0);
const date = value => value ? new Date(value).toLocaleString('vi-VN') : '—';
const lastPage = computed(()=>page.value==='customers' ? customers.value?.last_page||1 : page.value==='sales' ? Math.max(sales.value?.quotes.last_page||1,sales.value?.orders.last_page||1,sales.value?.payments.last_page||1) : page.value==='installations' ? Math.max(installations.value?.environments.last_page||1,installations.value?.operations.last_page||1) : page.value==='users' ? users.value?.last_page||1 : page.value==='tickets' ? tickets.value?.last_page||1 : audit.value?.last_page||1);
let epoch = 0, customerEpoch = 0, monitorTimer;
const lastSynced = ref(null);
async function load() {
    if (['security','notifications'].includes(page.value)) { epoch++; loading.value=false; return; }
    const token = ++epoch; loading.value = true; error.value = '';
    try {
        const key = page.value === 'overview' ? 'overview' : page.value === 'customers' ? `customers?page=${currentPage.value}&search=${encodeURIComponent(search.value)}` : page.value === 'sales' ? `sales?quotes_page=${currentPage.value}&orders_page=${currentPage.value}&payments_page=${currentPage.value}` : `${page.value}?page=${currentPage.value}&operations_page=${currentPage.value}`;
        const data = await props.api('admin/'+key);
        if (token !== epoch) return;
        if(page.value==='overview') overview.value=data;
        if(page.value==='customers') customers.value=data;
        if(page.value==='sales') sales.value=data;
        if(page.value==='installations') { installations.value=data; lastSynced.value=new Date(); }
        if(page.value==='tickets') tickets.value=data;
        if(page.value==='users') users.value=data;
        if(page.value==='settings') settings.value=data;
        if(page.value==='audit') audit.value=data;
    } catch(e) { if(token===epoch) error.value=e.message; }
    finally { if(token===epoch) loading.value=false; }
}
function navigate(value) { customerEpoch++; cancelTarget.value=null; sshCheck.value=''; page.value=value; currentPage.value=1; quote.value=null; payment.value=null; retryTarget.value=null; replyTarget.value=null; handover.value=null; credentialTarget.value=null; credentialPassword.value=''; credentialCurrent.value=''; sshForm.value.ssh_password=''; sshForm.value.current_password=''; notice.value=''; load(); }
async function act(path, body, success) {
    busy.value=true; error.value=''; notice.value='';
    try { const result=await props.api('admin/'+path,{method:'POST',body:JSON.stringify(body)}); notice.value=success; await load(); return result; }
    catch(e) { error.value=e.message; return null; } finally { busy.value=false; }
}
async function chooseCustomer(id) {
    const token=++customerEpoch; error.value=''; customer.value=null; sshCheck.value='';
    sshForm.value={ssh_host:'',ssh_port:22,ssh_user:'root',ssh_password:'',ssh_host_key:'',dedicated_server:false,current_password:''};
    installForm.value={driver:settings.value?.simulation_enabled ? 'simulation' : 'ssh',notes:'',confirmed:false};
    try { const result=await props.api('admin/customers/'+id); if(token===customerEpoch) { customer.value=result; selectedId.value=id; } }
    catch(e) { if(token===customerEpoch) { error.value=e.message; customer.value=null; } }
}
async function createCustomer() { const result=await act('customers',customerForm.value.create_owner ? customerForm.value : {name:customerForm.value.name,slug:customerForm.value.slug,owner_email:customerForm.value.owner_email},'Đã tạo khách hàng và gán chủ công ty.'); customerForm.value.owner_password='';customerForm.value.owner_password_confirmation='';customerForm.value.current_password=''; if(result) { showCreate.value=false; await chooseCustomer(result.id); navigate('installations'); } }
async function saveCustomer() { const result=await act('customers/'+customer.value.tenant.id,{name:customer.value.tenant.name,status:customer.value.tenant.status,contact_name:customer.value.tenant.contact_name,phone:customer.value.tenant.phone,tax_code:customer.value.tenant.tax_code,address:customer.value.tenant.address},'Đã lưu hồ sơ khách hàng. Tạm ngưng không tự tắt máy/RADIUS.'); if(result) await chooseCustomer(result.id); }
async function issueQuote() { const result=await act(`quotes/${quote.value.id}/issue`,{...quoteForm.value,amount_vnd:Number(quoteForm.value.amount_vnd),service_days:Number(quoteForm.value.service_days)},'Đã phát hành báo giá cho khách hàng.'); if(result) quote.value=null; }
async function verifyPayment() { const result=await act(`orders/${payment.value.id}/verify-payment`,{...paymentForm.value,amount_vnd:Number(paymentForm.value.amount_vnd)},'Đã đối soát và cập nhật thuê bao. Không thực hiện chuyển tiền.'); if(result) payment.value=null; }
async function install() {
    const id=customer.value.tenant.id;
    const result=await act(`customers/${id}/install`,{...installForm.value,...(installForm.value.driver==='ssh'?sshForm.value:{}),idempotency_key:crypto.randomUUID()},'Đã tạo tác vụ cài đặt. Theo dõi tiến trình phía dưới.');
    sshForm.value.ssh_password=''; sshForm.value.current_password='';
    if(result) { installForm.value.confirmed=false; sshForm.value.dedicated_server=false; await chooseCustomer(id); }
}
async function saveSshCredentials(action) {
    const result=await act(`environments/${credentialTarget.value.id}/ssh-credentials`,{action,current_password:credentialCurrent.value,...(action==='replace'?{ssh_password:credentialPassword.value}:{})},action==='replace'?'Đã thay mật khẩu SSH. Sau khi đối soát, thử lại tác vụ phía dưới.':'Đã xóa mật khẩu SSH đã lưu.');
    credentialPassword.value='';credentialCurrent.value='';if(result)credentialTarget.value=null;
}
async function checkSsh() {
    const id=customer.value.tenant.id, snapshot=JSON.stringify(sshForm.value), token=customerEpoch;
    busy.value=true;error.value='';sshCheck.value='';
    try { const value=await props.api('admin/customers/'+id+'/check-ssh',{method:'POST',body:snapshot}); if(token===customerEpoch && snapshot===JSON.stringify(sshForm.value))sshCheck.value=value.message; }
    catch(e){if(token===customerEpoch)error.value=e.message;}
    finally{busy.value=false;}
}
async function cancelOperation(){const result=await act('operations/'+cancelTarget.value.id+'/cancel',{confirmed:cancelChecked.value},'Đã hủy tác vụ chờ và xóa mật khẩu SSH. Không xóa máy chủ hoặc DNS.');if(result)cancelTarget.value=null;}
async function retryOperation() { const result=await act(`operations/${retryTarget.value.id}/retry`,{confirmed_reconciled:retryChecked.value},'Đã đưa tác vụ lỗi vào hàng đợi sau đối soát.'); if(result) retryTarget.value=null; }
async function finishHandover() { const result=await act(`environments/${handover.value.id}/handover`,acceptance.value,'Đã ghi nhận nghiệm thu và bàn giao của TN20.'); if(result) handover.value=null; }
async function sendReply() { const result=await act(`tickets/${replyTarget.value.id}/reply`,{reply:reply.value,status:closeTicket.value?'closed':'answered'},'Đã lưu phản hồi cho khách hàng.'); if(result) replyTarget.value=null; }
onMounted(async()=> {
    monitorTimer=setInterval(()=> { if(page.value==='installations' && !loading.value && !busy.value && !error.value && !retryTarget.value && !handover.value && !credentialTarget.value && !cancelTarget.value && document.visibilityState==='visible') load(); },10000);
    try { settings.value=await props.api('admin/settings'); } catch(e) { error.value=e.message; } await load();
});
onUnmounted(()=> { epoch++; customerEpoch++; clearInterval(monitorTimer); });
</script>

<template>
    <div class="workspace admin-workspace">
        <aside class="sidebar"><a class="brand" href="/admin">NAC<span>20</span><small>ADMIN</small></a><p class="admin-scope">QUẢN TRỊ NỀN TẢNG TN20</p><nav aria-label="Quản trị TN20"><button v-for="item in navigation" :key="item[0]" :class="{active:page===item[0]}" @click="navigate(item[0])"><span>{{item[1]}}</span>{{item[2]}}</button></nav><div class="sidebar-bottom"><a href="/">↗ Không gian khách hàng</a><p>Quyền toàn nền tảng</p></div></aside>
        <div class="main-area"><header class="topbar"><span>TN20 / <b>{{navigation.find(n=>n[0]===page)?.[2]}}</b></span><div><span class="badge">Admin TN20</span><span>{{user.name}}</span><button class="text-button" @click="emit('logout')">Đăng xuất</button></div></header><main class="content"><div class="page-heading"><div><p class="eyebrow">ĐIỀU HÀNH DỊCH VỤ NAC20</p><h1>{{navigation.find(n=>n[0]===page)?.[2]}}</h1><p class="muted">Quản lý khách hàng, mua bán và triển khai môi trường riêng.</p></div><button class="secondary" :disabled="loading" @click="load">↻ Cập nhật</button></div><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="success-notice" role="status">{{notice}}</p>
            <template v-if="page==='overview'"><section class="hero admin-hero"><div><p class="eyebrow">TRUNG TÂM VẬN HÀNH TN20</p><h2>Từ báo giá đến bàn giao.<br>Một quy trình được kiểm soát.</h2><p>Theo dõi khách hàng, đối soát thanh toán và cài đặt NAC20 trong cùng một không gian.</p><button class="light-button" @click="navigate('installations')">Cài đặt cho khách hàng →</button></div></section><section class="admin-stats"><article v-for="[key,title] in [['customers','Khách hàng'],['quotes_waiting','Chờ báo giá'],['payments_waiting','Chờ đối soát'],['environment_count','Môi trường NAC'],['failed_operations','Tác vụ lỗi'],['open_tickets','Hỗ trợ đang mở']]" :key="key"><span>{{title}}</span><strong>{{overview[key] ?? 0}}</strong></article></section><section class="panel"><p class="eyebrow">DOANH THU ĐÃ ĐỐI SOÁT</p><h2>{{money(overview.revenue_vnd)}}</h2><p class="muted">Tổng giao dịch đã xác nhận trên hệ thống; không bao gồm báo giá chưa thanh toán.</p></section></template>
            <template v-if="page==='customers'"><section class="panel"><div class="section-heading"><h2>Danh sách khách hàng</h2><button class="primary" @click="showCreate=!showCreate">Thêm khách hàng</button></div><form class="inline-form" @submit.prevent="currentPage=1;load()"><label>Tìm tên hoặc mã công ty<input v-model="search" maxlength="100" placeholder="Nhập tên hoặc mã…"></label><button class="secondary">Tìm kiếm</button></form><form v-if="showCreate" class="admin-form-box commerce-form" @submit.prevent="createCustomer"><label>Tên công ty<input v-model="customerForm.name" required maxlength="150"></label><label>Mã công ty<input v-model="customerForm.slug" pattern="[a-z0-9][a-z0-9-]{1,48}[a-z0-9]" required></label><label>Email chủ công ty<input v-model="customerForm.owner_email" type="email" required></label><label class="checkbox-label"><input v-model="customerForm.create_owner" type="checkbox"> Tạo tài khoản mới cho chủ công ty</label><template v-if="customerForm.create_owner"><label>Họ tên chủ tài khoản<input v-model="customerForm.owner_name" required maxlength="100"></label><label>Mật khẩu ban đầu cho khách<input v-model="customerForm.owner_password" type="password" autocomplete="new-password" minlength="12" maxlength="128" required></label><label>Nhập lại mật khẩu cho khách<input v-model="customerForm.owner_password_confirmation" type="password" autocomplete="new-password" required></label><label>Mật khẩu admin TN20 hiện tại<input v-model="customerForm.current_password" type="password" autocomplete="current-password" required></label><p class="muted">Không tự gửi email. TN20 bàn giao thông tin đăng nhập qua kênh riêng; khách bắt buộc đổi mật khẩu ở lần đăng nhập đầu tiên.</p></template><p v-else class="muted">Gán chủ công ty bằng email tài khoản đang hoạt động đã đăng ký.</p><button class="primary" :disabled="busy">Tạo khách hàng</button></form><div v-if="customers" class="table-scroll"><table><thead><tr><th>ID</th><th>Công ty</th><th>Mã</th><th>Trạng thái</th><th></th></tr></thead><tbody><tr v-for="item in customers.data" :key="item.id"><td>#{{item.id}}</td><td>{{item.name}}</td><td>{{item.slug}}</td><td><span class="badge">{{state(item.status)}}</span></td><td><button class="secondary" @click="chooseCustomer(item.id)">Quản lý</button></td></tr></tbody></table></div></section><section v-if="customer" class="panel"><div class="section-heading"><h2>{{customer.tenant.name}}</h2><button class="primary" @click="navigate('installations')">Cài đặt NAC20 →</button></div><form class="commerce-form" @submit.prevent="saveCustomer"><div class="form-columns"><label>Tên công ty<input v-model="customer.tenant.name" required maxlength="150"></label><label>Trạng thái<select v-model="customer.tenant.status"><option value="active">Hoạt động</option><option value="suspended">Tạm ngưng tác vụ mới</option></select></label><label>Người liên hệ<input v-model="customer.tenant.contact_name" maxlength="120"></label><label>Điện thoại<input v-model="customer.tenant.phone" maxlength="40"></label><label>Mã số thuế<input v-model="customer.tenant.tax_code" maxlength="40"></label><label>Địa chỉ<input v-model="customer.tenant.address" maxlength="500"></label></div><p class="notice">Tạm ngưng chỉ chặn tác vụ mới trên cổng, không tự tắt máy chủ hoặc dịch vụ mạng đang vận hành.</p><button class="primary" :disabled="busy">Lưu hồ sơ</button></form><h3>Thành viên công ty</h3><div class="table-scroll"><table><thead><tr><th>Họ tên</th><th>Email</th><th>Vai trò</th></tr></thead><tbody><tr v-for="member in customer.members" :key="member.id"><td>{{member.name}}</td><td>{{member.email}}</td><td>{{member.pivot.role}}</td></tr></tbody></table></div></section></template>
            <template v-if="page==='sales' && sales"><section class="panel"><h2>Yêu cầu báo giá</h2><div class="table-scroll"><table><thead><tr><th>Yêu cầu / Công ty</th><th>Gói / Nhu cầu</th><th>Trạng thái</th><th></th></tr></thead><tbody><tr v-for="item in sales.quotes.data" :key="item.id"><td>#{{item.id}} / Công ty #{{item.tenant_id}}</td><td>{{item.plan_code}} · {{item.devices}} thiết bị / {{item.branches}} chi nhánh<p class="preserve-text">{{item.requirements}}</p></td><td>{{state(item.status)}}</td><td><button v-if="item.status==='requested'" class="secondary" @click="quote=item;quoteForm={amount_vnd:'',service_days:30,terms:''}">Lập báo giá</button></td></tr></tbody></table></div></section><section v-if="quote" class="panel"><h2>Báo giá yêu cầu #{{quote.id}} · Công ty #{{quote.tenant_id}}</h2><form class="commerce-form" @submit.prevent="issueQuote"><div class="form-columns"><label>Tổng tiền VND<input v-model="quoteForm.amount_vnd" type="number" min="1000" max="1000000000000" step="1" required></label><label>Thời hạn dịch vụ (ngày)<input v-model="quoteForm.service_days" type="number" min="1" max="366" required></label></div><label>Phạm vi, thuế/phí và điều khoản<textarea v-model="quoteForm.terms" rows="5" minlength="10" maxlength="12000" required></textarea></label><p class="muted">Chỉ nhập giá đã duyệt. Báo giá có hạn xác nhận 7 ngày.</p><button class="primary" :disabled="busy">Phát hành báo giá</button><button type="button" class="text-button" @click="quote=null">Đóng</button></form></section><section class="panel"><h2>Đơn hàng và đối soát</h2><div class="table-scroll"><table><thead><tr><th>Đơn / Công ty</th><th>Tổng tiền</th><th>Trạng thái</th><th></th></tr></thead><tbody><tr v-for="item in sales.orders.data" :key="item.id"><td>{{item.number}}<small class="block-muted">Công ty #{{item.tenant_id}}</small></td><td>{{money(item.amount_vnd)}}</td><td>{{state(item.status)}}</td><td><button v-if="['pending_payment','pending_review'].includes(item.status)" class="secondary" @click="payment=item;paymentForm={reference:'',amount_vnd:item.amount_vnd,confirmed_received:false,defer_installation:true}">Đối soát</button></td></tr></tbody></table></div></section><section v-if="payment" class="panel"><h2>Đối soát {{payment.number}} · Công ty #{{payment.tenant_id}}</h2><form class="commerce-form" @submit.prevent="verifyPayment"><label>Tham chiếu giao dịch thực nhận<input v-model="paymentForm.reference" required pattern="[A-Za-z0-9._:-]{4,120}"></label><label>Số tiền thực nhận VND<input v-model="paymentForm.amount_vnd" type="number" min="1000" required></label><label class="checkbox-label"><input v-model="paymentForm.confirmed_received" type="checkbox" required> Tôi đã kiểm tra giao dịch ngân hàng, công ty nhận dịch vụ và số tiền.</label><label class="checkbox-label"><input v-model="paymentForm.defer_installation" type="checkbox"> Để admin chọn máy và cài SSH sau đối soát (chưa tự cấp môi trường)</label><p class="notice">Xác nhận sẽ kích hoạt/gia hạn và có thể tạo tác vụ cấp phát theo cấu hình. Không có thao tác chuyển tiền.</p><button class="primary" :disabled="busy">Xác nhận đã nhận tiền</button><button type="button" class="text-button" @click="payment=null">Đóng</button></form></section><section class="panel"><h2>Giao dịch đã đối soát</h2><div class="table-scroll"><table><thead><tr><th>Đơn / Công ty</th><th>Số tiền</th><th>Tham chiếu</th><th>Ngày xác nhận</th></tr></thead><tbody><tr v-for="item in sales.payments.data" :key="item.id"><td>#{{item.order_id}} / #{{item.tenant_id}}</td><td>{{money(item.amount_vnd)}}</td><td>{{item.reference}}</td><td>{{date(item.verified_at)}}</td></tr></tbody></table></div></section></template>
            <template v-if="page==='installations'"><p class="fine" role="status">Danh sách tự cập nhật mỗi 10 giây khi tab đang mở. Lần cập nhật: {{lastSynced ? lastSynced.toLocaleTimeString('vi-VN') : 'Đang tải…'}}. Tạm dừng khi đang xử lý hoặc nghiệm thu.</p><section class="panel"><h2>Cài NAC20 cho khách hàng</h2><form class="inline-form" @submit.prevent="chooseCustomer(Number(selectedId))"><label>ID khách hàng<input v-model="selectedId" @input="customerEpoch++;customer=null;sshForm.ssh_password='';sshForm.current_password='';installForm.confirmed=false" type="number" min="1" required placeholder="Chọn từ mục Khách hàng hoặc nhập ID"></label><button class="secondary">Tải hồ sơ</button></form><template v-if="customer"><div class="notice"><b>{{customer.tenant.name}} · #{{customer.tenant.id}}</b><p>Tên miền dự kiến: {{customer.tenant.slug}}.{{settings?.domain}}</p><p>Thuê bao đến: {{date(customer.subscription?.expires_at)}}</p></div><p v-if="customer.environments.length" class="muted">Khách đã có môi trường. Hệ thống chặn cài đè; theo dõi hoặc thử lại tác vụ lỗi phía dưới.</p><form v-else class="commerce-form" @submit.prevent="install"><label>Phương thức cài đặt<select v-model="installForm.driver"><option v-if="settings?.simulation_enabled" value="simulation">Mô phỏng — không tạo máy chủ</option><option value="ssh">Máy chủ có sẵn — SSH bằng mật khẩu</option><option v-if="settings?.live_enabled" value="hetzner">Tạo VM Hetzner + DNS + Ansible</option></select></label><template v-if="installForm.driver==='ssh'"><p v-if="!settings?.live_enabled || !settings?.ssh_enabled" class="notice">Cài SSH thật đang tắt. TN20 cần bật PROVISIONING_ENABLED và SSH_INSTALL_ENABLED trên worker; khách cần có thuê bao hiệu lực.</p><div class="form-columns"><label>IPv4 công khai máy chủ<input v-model="sshForm.ssh_host" required placeholder="IP máy chủ riêng của khách"></label><label>Cổng SSH<input v-model.number="sshForm.ssh_port" type="number" min="1" max="65535" required></label><label>Tài khoản SSH<input v-model="sshForm.ssh_user" required maxlength="32" pattern="[a-z_][a-z0-9_-]{0,31}"></label><label>Mật khẩu SSH của máy chủ<input v-model="sshForm.ssh_password" type="password" autocomplete="off" maxlength="1024" required></label></div><label>Khóa công khai máy chủ SSH (Ed25519)<textarea v-model="sshForm.ssh_host_key" rows="3" required maxlength="512" placeholder="ssh-ed25519 AAAA…"></textarea></label><p class="fine">Lấy bằng lệnh cat /etc/ssh/ssh_host_ed25519_key.pub tại console tin cậy của VPS. Đây là khóa công khai, không phải private key. Backend kiểm tra đúng khóa này khi SSH.</p><label>Mật khẩu tài khoản admin TN20 hiện tại<input v-model="sshForm.current_password" type="password" autocomplete="current-password" required></label><label class="checkbox-label"><input v-model="sshForm.dedicated_server" type="checkbox" required> Đây là máy Debian 12 amd64 riêng, tối thiểu 16 GB RAM / 200 GB đĩa, được phép cài NAC20. Đã sao lưu dữ liệu cần giữ.</label><button type="button" class="secondary" :disabled="busy || !settings?.live_enabled || !settings?.ssh_enabled" @click="checkSsh">Kiểm tra SSH trước khi cài</button><p v-if="sshCheck" class="success-notice" role="status">{{sshCheck}}</p><p class="muted">Mật khẩu máy chủ được mã hóa, không trả lại qua API, xóa sau khi cài thành công. Máy cài lỗi giữ mật khẩu mã hóa để thử lại; admin có thể thay/xóa trong danh sách môi trường. Tài khoản SSH cần root hoặc sudo; mật khẩu sudo dùng cùng mật khẩu SSH.</p></template><label>Ghi chú triển khai<textarea v-model="installForm.notes" maxlength="3000" rows="3" placeholder="Phạm vi và yêu cầu cấu hình; không nhập mật khẩu hoặc token."></textarea></label><p class="muted">Bản cài được khóa theo URL và SHA-256 trong cấu hình TN20. Khóa SSH/API chỉ đặt trên worker.</p><label class="checkbox-label"><input v-model="installForm.confirmed" type="checkbox" required> Đã kiểm tra đúng khách hàng, điều kiện thuê bao và phương thức cài đặt.</label><button class="primary" :disabled="busy || !installEnabled">Tạo tác vụ cài đặt NAC20</button></form></template></section><section v-if="installations" class="panel"><h2>Môi trường đã tạo</h2><div class="table-scroll"><table><thead><tr><th>Môi trường / Khách</th><th>IP / Phương thức</th><th>Trạng thái</th><th></th></tr></thead><tbody><tr v-for="item in installations.environments.data" :key="item.id"><td>{{item.hostname}}<small class="block-muted">Công ty #{{item.tenant_id}}</small></td><td>{{item.ip_address || 'Chưa cấp'}}<small class="block-muted">{{item.driver}}</small></td><td>{{state(item.status)}}</td><td><button v-if="item.driver==='ssh' && ['failed','cancelled'].includes(item.status)" class="secondary" @click="credentialTarget=item;credentialPassword='';credentialCurrent=''">Thay / xóa mật khẩu SSH</button><button v-if="item.status==='awaiting_configuration'" class="secondary" @click="handover=item;acceptance={database_checked:false,tls_checked:false,connector_checked:false,radius_checked:false,backup_checked:false,evidence:''}">Nghiệm thu / Bàn giao</button></td></tr></tbody></table></div></section><section v-if="installations" class="panel"><h2>Tác vụ cài đặt</h2><div class="table-scroll"><table><thead><tr><th>ID / Khách</th><th>Trạng thái</th><th>Bước / Lỗi</th><th></th></tr></thead><tbody><tr v-for="item in installations.operations.data" :key="item.id"><td>#{{item.id}} / #{{item.tenant_id}}</td><td>{{state(item.status)}}</td><td>{{state(item.stage)}}<small class="error-code">{{item.error_code}}</small></td><td><button v-if="item.status==='queued'" class="secondary" @click="cancelTarget=item;cancelChecked=false">Hủy tác vụ chờ</button><button v-if="['failed','cancelled'].includes(item.status)" class="secondary" @click="retryTarget=item;retryChecked=false">Thử lại / Khởi động lại</button></td></tr></tbody></table></div></section><section v-if="cancelTarget" class="panel"><h2>Hủy tác vụ #{{cancelTarget.id}}</h2><p class="notice">Chỉ hủy khi worker chưa nhận việc. Mật khẩu SSH đã lưu sẽ bị xóa. Máy chủ, DNS và phần cài từ lần trước được giữ để TN20 đối soát.</p><label class="checkbox-label"><input v-model="cancelChecked" type="checkbox"> Đã kiểm tra đúng khách hàng và đồng ý hủy tác vụ chờ</label><button class="primary" :disabled="busy || !cancelChecked" @click="cancelOperation">Xác nhận hủy tác vụ</button><button class="text-button" @click="cancelTarget=null">Quay lại</button></section><section v-if="credentialTarget" class="panel"><h2>Thông tin SSH · {{credentialTarget.hostname}}</h2><form class="commerce-form" @submit.prevent="saveSshCredentials('replace')"><label>Mật khẩu SSH mới<input v-model="credentialPassword" type="password" autocomplete="off" maxlength="1024"></label><label>Mật khẩu admin TN20 hiện tại<input v-model="credentialCurrent" type="password" autocomplete="current-password" required></label><button class="primary" :disabled="busy || !credentialPassword">Lưu mật khẩu SSH mới</button><button class="secondary" type="button" :disabled="busy" @click="saveSshCredentials('forget')">Xóa mật khẩu SSH đã lưu</button><button class="text-button" type="button" @click="credentialTarget=null;credentialPassword='';credentialCurrent=''">Hủy</button></form></section><section v-if="retryTarget" class="panel"><h2>Thử lại tác vụ #{{retryTarget.id}}</h2><label class="checkbox-label"><input v-model="retryChecked" type="checkbox"> Đã đối soát máy chủ, SSH host key và nguyên nhân lỗi; không tạo máy trùng.</label><button class="primary" :disabled="busy || !retryChecked" @click="retryOperation">Đưa vào hàng đợi</button></section><section v-if="handover" class="panel"><h2>Nghiệm thu {{handover.hostname}}</h2><p class="muted">Đây là xác nhận của TN20 sau khi kiểm tra thực tế, không phải kiểm thử tự động bằng checkbox.</p><form class="commerce-form" @submit.prevent="finishHandover"><label v-for="[key,text] in [['database_checked','Cơ sở dữ liệu và tài khoản riêng'],['tls_checked','TLS tin cậy và tên miền'],['connector_checked','Connector đúng công ty đã kết nối'],['radius_checked','Đã thử RADIUS/MAB và quyền truy cập thực tế'],['backup_checked','Đã kiểm tra sao lưu/khôi phục']]" :key="key" class="checkbox-label"><input v-model="acceptance[key]" type="checkbox" required>{{text}}</label><label>Kết quả kiểm tra và tham chiếu biên bản<textarea v-model="acceptance.evidence" minlength="20" maxlength="4000" rows="4" required></textarea></label><button class="primary" :disabled="busy">Ghi nhận bàn giao</button></form></section></template>
            <section v-if="page==='tickets' && tickets" class="panel"><h2>Yêu cầu hỗ trợ</h2><article v-for="item in tickets.data" :key="item.id" class="ticket-item"><div class="section-heading"><h3>#{{item.id}} · {{item.subject}} · Công ty #{{item.tenant_id}}</h3><span class="badge">{{state(item.status)}}</span></div><p class="preserve-text">{{item.message}}</p><p v-if="item.reply" class="notice preserve-text">{{item.reply}}</p><button class="secondary" @click="replyTarget=item;reply=item.reply||'';closeTicket=false">Phản hồi</button><form v-if="replyTarget?.id===item.id" class="commerce-form admin-form-box" @submit.prevent="sendReply"><label>Nội dung phản hồi<textarea v-model="reply" minlength="5" maxlength="6000" rows="4" required></textarea></label><label class="checkbox-label"><input v-model="closeTicket" type="checkbox"> Đóng yêu cầu sau phản hồi</label><button class="primary" :disabled="busy">Lưu phản hồi</button></form></article></section>
            <section v-if="page==='users' && users" class="panel"><h2>Tài khoản nền tảng</h2><p class="muted">Quyền admin TN20 chỉ được cấp/thu hồi tại console tin cậy, không qua màn hình này.</p><div class="table-scroll"><table><thead><tr><th>Họ tên / Email</th><th>Loại tài khoản</th><th>Trạng thái</th><th></th></tr></thead><tbody><tr v-for="item in users.data" :key="item.id"><td>{{item.name}}<small class="block-muted">{{item.email}}</small></td><td>{{item.is_platform_admin?'Admin TN20':'Khách hàng'}}</td><td>{{item.is_active?'Hoạt động':'Đã khóa'}}</td><td><button v-if="!item.is_platform_admin" class="secondary" :disabled="busy" @click="act('users/'+item.id,{is_active:!item.is_active},'Đã cập nhật trạng thái tài khoản.')">{{item.is_active?'Khóa đăng nhập':'Mở khóa'}}</button></td></tr></tbody></table></div></section>
            <NotificationsPanel v-if="page==='notifications'" :api="api"/><SecurityPanel v-if="page==='security'" :api="api"/><section v-if="page==='settings' && settings" class="panel"><h2>Điều kiện triển khai</h2><dl class="environment-facts"><div><dt>Vùng DNS</dt><dd>{{settings.domain}}</dd></div><div><dt>Chế độ mô phỏng</dt><dd>{{settings.simulation_enabled ? "Chỉ dùng để kiểm thử" : "Đã tắt trên production"}}</dd></div><div><dt>Cấp phát thật</dt><dd>{{settings.live_enabled?'Đã bật':'Đang tắt'}}</dd></div><div><dt>Thông tin chuyển khoản</dt><dd>{{settings.bank_configured?'Đã cấu hình':'Chưa cấu hình'}}</dd></div><div><dt>Khôi phục mật khẩu qua email</dt><dd>{{settings.password_recovery_enabled?"Đã bật cấu hình SMTP / HTTPS":"Chưa bật hoặc thiếu cấu hình"}}</dd></div><div><dt>Phương thức mặc định</dt><dd>{{settings.default_driver}}</dd></div></dl><p class="notice">Thông tin dưới đây chỉ cho biết đã khai báo, chưa chứng minh token còn hiệu lực hoặc SSH kết nối được. Bí mật chỉnh tại cấu hình vận hành, không trả về trình duyệt.</p><div class="settings-checks"><p v-for="(value,key) in settings.checks" :key="key"><code>{{key}}</code><span :class="['badge',{danger:!value}]">{{value?'Đã khai báo':'Chưa khai báo'}}</span></p></div><h3>Bản cài NAC20</h3><p class="preserve-text">{{settings.release_url || 'Chưa chọn bản cài'}}</p><code>{{settings.release_sha256 || 'Chưa có SHA-256'}}</code></section>
            <section v-if="page==='audit' && audit" class="panel"><h2>Nhật ký quản trị nền tảng</h2><div class="table-scroll"><table><thead><tr><th>Thời gian</th><th>Admin</th><th>Hành động</th><th>Khách / Đối tượng</th></tr></thead><tbody><tr v-for="item in audit.data" :key="item.id"><td>{{date(item.created_at)}}</td><td>{{item.user_id ? '#'+item.user_id : 'Console TN20'}}</td><td>{{item.action}}</td><td>{{item.tenant_id ? '#'+item.tenant_id : 'Nền tảng'}} / #{{item.subject}}</td></tr></tbody></table></div></section>
            <div v-if="['customers','sales','installations','tickets','users','audit'].includes(page)" class="pagination"><button :disabled="currentPage<=1 || loading" @click="currentPage--;load()">←</button><span>Trang {{currentPage}}</span><button :disabled="loading || currentPage>=lastPage" @click="currentPage++;load()">→</button></div><p v-if="loading" class="fine" role="status">Đang tải…</p><footer class="content-footer">NAC20 Cloud · Quản trị TN20<span>Mọi thao tác quản trị được kiểm tra tại backend</span></footer>
        </main></div>
    </div>
</template>
